/* Fixed workspace chrome, scrollable records; no data changes. */
(function(){const previous=render;render=function(){previous();if(page==='工作台'&&!selected)return;const content=document.querySelector('.content');if(!content)return;content.classList.add('window-content');if(selected){content.classList.add('window-detail');const area=document.createElement('div');area.className='workspace-scroll';[...content.children].filter(el=>!el.classList.contains('heading')&&!el.classList.contains('project-summary')&&!el.classList.contains('tabs')&&!el.classList.contains('bottomnote')).forEach(el=>area.append(el));content.append(area);return}if(page==='项目台账'){content.classList.add('window-ledger');return}if(page==='待办与风险'){content.classList.add('window-today');return}const area=document.createElement('div');area.className='workspace-scroll';[...content.children].filter(el=>!el.classList.contains('heading')&&!el.classList.contains('bottomnote')).forEach(el=>area.append(el));content.append(area)}})();
